async function launch(sub,name){const file=name==='audit'?'process-audit.cjs':name+'-probes.cjs',fd=fs.openSync(p.join(sub,file+'.log'),'wx'),child=cp.spawn(process.execPath,[p.join(sub,file)],{cwd:sub,stdio:['ignore',fd,fd]});fs.closeSync(fd);const exit=await new Promise((res,rej)=>{child.once('error',rej);child.once('close',res);});if(exit!==0)throw Error('Infrastructure failed '+file+' exit '+exit);return {file,exit,phase:read(sub,'progress.json').count};}
