const out={actual_controller_source:fs.readFileSync(__filename,'utf8'),controller_kind:'V2 serial all old controls after static setup closed; original failed parallel control and exact isolated diagnostic retained, no attribution of exact stall cause',initial_failure_file:p.join(root,'environment-preflight-error.json'),initial_failure_sha256:hash(fs.readFileSync(p.join(root,'environment-preflight-error.json'))),isolated_diagnostic_file:p.join(root,'preflight-positive-control-diagnostic.json'),isolated_diagnostic_sha256:hash(fs.readFileSync(p.join(root,'preflight-positive-control-diagnostic.json'))),status:'PASS',started_at,finished_at:new Date().toISOString(),kind:'Fresh actual closed11 artifacts: all54 at6, new8 at42; same Python/input/oracle/pass-fail and original46/i18n bytes. Two recorded failed traces and six family-accounting replays. Zero-owned-live phase audits. No new candidate quality claim.',environments,launches,reports,phase42reports,failed_accounting_replay:accounting,first6_candidate_scores:scores,previous_progress_sha256:hash(fs.readFileSync(p.join(prior,'progress.json'))),controllers_sha256:Object.fromEntries(groups.map(([n])=>[n+'-probes.cjs',hash(fs.readFileSync(p.join(root,n+'-probes.cjs')))])),twelfth_models_executed:0};fs.writeFileSync(p.join(root,'environment-preflight.json'),JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({status:'PASS',models_executed:0,candidate_scores:scores,accounting_replays:accounting.length}));})().catch(e=>{fs.writeFileSync(p.join(root,'environment-preflight-v2-error.json'),JSON.stringify({status:'FAIL',at:new Date().toISOString(),error:String(e),twelfth_models_executed:0},null,2)+'\n');console.error(e.stack);process.exitCode=1;});
